def transform(grid):
    # Identify the non-background structured object, then translate it so
    # each marker occupies the seed object's anchor cell.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    from collections import deque
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]!=bg:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append(cells)
    # The seed is the largest component containing the minority foreground
    # color(s); isolated singleton components are marker anchors.
    seed=max(comps,key=len)
    markers=[comp[0] for comp in comps if len(comp)==1]
    minr=min(r for r,c in seed); maxr=max(r for r,c in seed)
    minc=min(c for r,c in seed); maxc=max(c for r,c in seed)
    # Anchor is the unique-color marker-like cell within seed, when present;
    # otherwise use the central cell of the seed's bounding rectangle.
    colors={grid[r][c] for r,c in seed}
    counts={v:sum(grid[r][c]==v for r,c in seed) for v in colors}
    anchor_candidates=[(r,c) for r,c in seed if counts[grid[r][c]]==1]
    ar,ac=anchor_candidates[0] if anchor_candidates else ((minr+maxr)//2,(minc+maxc)//2)
    out=[row[:] for row in grid]
    for mr,mc in markers:
        dr,dc=mr-ar,mc-ac
        for r,c in seed:
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w:
                out[rr][cc]=grid[r][c]
    return out

